 sky(93,[
 ['Untersuche, was mit bereits bekannten Commit-Kennungen und darauf aufgebauter Arbeit geschieht.','Ein Teammitglied hat auf einer veröffentlichten Änderung weitergearbeitet. Welche Folgen hat es, wenn deren Historie nachträglich anders aufgebaut wird?'],
 ['Beide Ansätze bereiten Änderungen automatisiert vor. Achte auf den letzten Schritt in die Produktion.','Eine Pipeline erzeugt ein freigabefähiges Paket. Muss vor der produktiven Bereitstellung noch jemand ausdrücklich entscheiden?'],
 ['Trenne vertrauliche Zugangsdaten vom veröffentlichten Quelltext und von Ausgaben.','Ein Datenbankpasswort wird für einen Auslieferungsschritt gebraucht. Welche Nachteile hätte es, dieses Passwort in einer eingecheckten Datei zu hinterlegen?'],
 ['Ordne frühe Fehlererkennung, Paketbildung und kontrollierte Auslieferung in eine nachvollziehbare Reihenfolge.','Bei einer Web-Anwendung sollten fehlerhafte Tests verhindern, dass ein ungeprüftes Paket produktiv bereitgestellt wird. Wo liegen passende Prüfpunkte?']
 ]);
 sky(97,[
 ['Die drei Versionsbestandteile unterscheiden Änderungen nach ihrer Verträglichkeit.','Ein bisher erforderliches API-Feld wird anders interpretiert, sodass bestehende Clients angepasst werden müssen. Ist das nur eine Fehlerkorrektur?'],
 ['Überlege, was Nutzende und Betrieb beim Wechsel einer Version wissen müssen.','Ein Update verändert Verhalten und benötigt einen zusätzlichen Einrichtungsschritt. Wo sollten diese Auswirkungen verständlich nachzulesen sein?'],
 ['Denke an zwei getrennte Umgebungen und einen kontrollierten Wechsel des Verkehrs.','Eine neue Fassung wird vorbereitet, während die bisherige noch Anfragen bedient. Welcher Vorteil entsteht, wenn du den Verkehr gezielt umschalten kannst?'],
 ['Begrenze zunächst den Schaden und kläre die Folgen für bereits geschriebene Daten.','Ein neues Release erzeugt doppelte Reservierungen. Wie prüfst du vor einer Rückkehr zur alten Version, welche Daten inzwischen korrigiert werden müssen?']
 ]);
 sky(101,[
 ['Entscheidend ist die Trennung zwischen einer Abfragestruktur und den eingesetzten Datenwerten.','Ein Suchtext enthält ein Hochkomma. Sollte dieser Text als normaler Wert behandelt werden oder die Struktur der Datenbankanfrage verändern dürfen?'],
 ['Überlege, ob ein gestohlener Datenbankeintrag das ursprüngliche Passwort direkt preisgeben darf.','Zwei Konten verwenden dasselbe Passwort. Welche zusätzlichen Schutzmerkmale verhindern einfache Vergleiche und erschweren massenhaftes Durchprobieren?'],
 ['Eine gültige Anmeldung sagt noch nicht, auf welchen konkreten Datensatz jemand zugreifen darf.','Ein angemeldeter Kunde verändert eine Rechnungsnummer in der URL. Welche weitere Prüfung muss vor der Ausgabe dieser Rechnung erfolgen?'],
 ['Unterscheide Identitätsprüfung, Rechte am konkreten Objekt und einen Test mit fremden Objekten.','Konto A darf seine eigene Rechnung abrufen. Welche Reaktion erwartest du beim Abruf einer Rechnung von Konto B?']
 ]);
 sky(105,[
 ['Betrachte den Weg von einer fachlichen Forderung bis zum überprüfbaren Ergebnis.','Eine Regel zur Terminvergabe sollte im Entwurf, in der Umsetzung und in passenden Nachweisen wiederzufinden sein.'],
 ['Ein Zwischenstand sollte eine konkrete Überprüfung und eine Entscheidung ermöglichen.','Nach einem Prototyp wird die Bedienung gemeinsam geprüft, bevor die komplette Oberfläche entsteht. Welches Risiko kann dieser Punkt früh sichtbar machen?'],
 ['Verbinde eine technische Wahl mit einem konkreten Bedarf und ihren Folgen.','„Wir nutzen das, weil es modern ist“ erklärt wenig. Welche Angaben zu Anforderungen, Alternativen und Nachteilen würden die Aussage belastbar machen?'],
 ['Wähle kleine durchgängige Ergebnisse, die jeweils beobachtbar funktionieren.','Für eine Reservierung könnten Eingabeprüfung, gespeicherte Buchung und kontrollierte Bereitstellung einzeln demonstrierbare Zwischenstände ergeben.']
 ]);
 sky(109,[
 ['Achte auf den Arbeitsauftrag und den verlangten Umfang der Antwort.','„Nennen“ fordert etwas anderes als „Begründen“. Was musst du zusätzlich liefern, wenn nach einer Begründung gefragt wird?'],
 ['Eine Empfehlung wird verständlich, wenn Auswahl und fachliche Gründe zusammenpassen.','Bei einer Datenbankwahl sollte erkennbar sein, welches Problem eine Alternative löst und welchen Nachteil du bewusst in Kauf nimmst.'],
 ['Betrachte verfügbare Zeit, Gewichtung und eine kurze Kontrolle am Ende gemeinsam.','Eine Teilaufgabe zählt nur wenige Punkte. Welche Folge hat es für den Rest, wenn du dort fast die gesamte Prüfungszeit verbrauchst?'],
 ['Ordne jeder Maßnahme ein konkretes Problem und einen nachvollziehbaren Nutzen zu.','Bei einer Reservierung sind unvollständige Datenänderungen, fremde Datensätze und fehlerhafte Zusammenarbeit unterschiedliche Risiken. Welche Maßnahme behandelt welches Risiko?']
 ]);
 unit(4,1,[['Suche nach beobachtbaren Bedingungen und einem eindeutigen Maßstab.','„Angenehm schnell“ lässt Interpretationen zu. Wie lässt sich eine Reaktionszeit mit Last und Grenzwert überprüfbar beschreiben?'],['Unterscheide vorbeugendes Gestalten von nachträglichem Untersuchen.','Ein gemeinsam vereinbarter Entwurfsstandard soll bestimmte Fehler schon bei der Entwicklung verhindern. Ein Test sucht sie erst im Ergebnis.'],['Prüfe, welchen Ausschnitt die genannten Tests tatsächlich abdecken.','Einzelne Berechnungen stimmen. Trotzdem kann das Zusammenspiel mit der Datenbank oder die Bedienung für Nutzende scheitern.'],['Verbinde eine messbare Eigenschaft mit vorbeugenden und untersuchenden Maßnahmen.','Bei einer Suchfunktion könnte eine vereinbarte Antwortzeit unter definierter Last geprüft werden. Welche Maßnahmen unterstützen sie schon im Entwurf?']]);
 unit(4,2,[['Überlege, wie eine Anforderung mit ihrem Prüfnachweis verbunden wird.','Eine Regel zur Rechnungsfreigabe ändert sich. Wie findest du die Tests, die diese Regel absichern sollen?'],['Einzelne Methoden und das Zusammenspiel realer Bausteine sind verschiedene Prüfgegenstände.','Eine API soll mit einer Datenbank speichern. Welche Fehler erkennst du nur, wenn beide gemeinsam beteiligt sind?'],['Ein Plan klärt vorab, was unter welchen Bedingungen durch wen geprüft wird.','Ein Testteam braucht neben Fällen auch eine Umgebung, Zuständigkeiten und eine Aussage, wann die Prüfung ausreichend ist.'],['Prüfe erlaubte und unerlaubte Nutzung derselben Funktion.','Bei einer Löschfunktion könnte die zuständige Rolle erfolgreich löschen, eine andere Rolle jedoch abgewiesen werden. Was wäre jeweils der erwartete Nachweis?']]);
 unit(4,3,[['Betrachte Werte direkt an erlaubten Grenzen und unmittelbar daneben.','Für eine erlaubte Anzahl von 2 bis 8 wären 1, 2, 3 sowie 7, 8, 9 interessante Werte. Übertrage das auf den gefragten Bereich.'],['Ein Ergebnis lässt sich nur bewerten, wenn vorher klar ist, was erwartet wird.','Nach einem ungültigen Datum erscheint eine Meldung. Welche genaue Erwartung brauchst du, um den Test als bestanden oder fehlgeschlagen einzuordnen?'],['Überlege, wann mehrere Bedingungen gemeinsam das Ergebnis bestimmen.','Ein Versandrabatt hängt gleichzeitig von Mitgliedschaft, Bestellwert und Lieferland ab. Wie behältst du die Kombinationen systematisch im Blick?'],['Untersuche beide Bedingungen sowie Werte direkt unter und an der Schwelle.','Für eine andere Aktion ab 50 Euro kannst du Mitglied und Nichtmitglied jeweils mit 49,99 und 50 Euro vergleichen.']]);
 unit(4,4,[['Vergleiche einen festen, bekannten Startzustand mit wechselnden unbekannten Voraussetzungen.','Ein Test findet einen Datensatz nur manchmal, weil frühere Tests ihn verändern. Wie könntest du die Ausgangslage kontrollieren?'],['Du brauchst passende Fälle, ohne unnötig echte personenbezogene Daten zu verbreiten.','Für eine Adressprüfung lassen sich eigens erfundene Anschriften mit gezielt eingebauten Sonderfällen verwenden.'],['Achte auf Wiederholbarkeit und darauf, ob das Ergebnis eindeutig geprüft werden kann.','Eine wiederkehrende Preisberechnung hat feste Eingaben und erwartete Werte. Ein erstmaliger kreativer Bedienungstest hat andere Voraussetzungen.'],['Plane Komponenten, kontrollierte Daten, Ausgangszustand und wiederholbare Ausführung.','Bei einer Reservierungs-API müssen etwa Datenbankversion, verfügbare Plätze und das Zurücksetzen nach einem Test festgelegt sein.']]);
 unit(4,5,[['Eine andere Person muss den Fehler unter denselben Voraussetzungen erneut auslösen können.','„Export kaputt“ reicht selten. Was müsste ein Kollege über Version, Eingabe, Schritte und beobachtetes Ergebnis wissen?'],['Trenne die Stärke der Auswirkung von der Entscheidung über die Bearbeitungsreihenfolge.','Ein kleiner sichtbarer Fehler kann vor einer wichtigen Vorführung dringlicher sein als ein seltener schwerer Fehler mit brauchbarer Umgehung.'],['Mehrere gemeldete Fehler müssen gemeinsam eingeordnet und zur Bearbeitung zugeordnet werden.','Ein Team prüft neue Meldungen auf Nachvollziehbarkeit, Auswirkungen und Zuständigkeit. Welche Entscheidung soll daraus entstehen?'],['Beschreibe reproduzierbare Schritte und stelle erwartetes und beobachtetes Verhalten gegenüber.','Bei einer Suche ohne Treffer könnte ein leerer Export erwartet werden. Welche Angaben braucht der Bericht, wenn die Anwendung stattdessen abstürzt?']]);
 unit(4,6,[['Ein ausgeführter Codeabschnitt ist noch keine inhaltlich aussagekräftige Prüfung.','Ein Test führt eine Berechnung aus, vergleicht ihr Ergebnis aber nie mit einem erwarteten Wert. Was belegt seine Abdeckung dann?'],['Eine Empfehlung sollte Ergebnisse, offene Risiken und Grenzen der Prüfung verständlich verbinden.','Ein Bericht meldet viele bestandene Tests, verschweigt aber eine ungeprüfte Zahlungsanbindung. Welche Information fehlt der Freigabeentscheidung?'],['Eine umgesetzte Maßnahme und eine nachgewiesene Verbesserung sind zwei verschiedene Schritte.','Ein Team führt Reviews ein. Wie zeigt es später, ob Fehler tatsächlich früher gefunden werden?'],['Suche eine mögliche Ursache, vereinbare eine Maßnahme und plane einen Vergleich danach.','Wenn Integrationsfehler erst spät auffallen, könnte ein früherer gemeinsamer Test helfen. Woran würdest du seine Wirkung erkennen?']]);
 unit(5,1,[['Denke an Vorwissen, Aufgabe und Nutzungssituation der lesenden Person.','Eine erfahrene Entwicklerin braucht andere Details als jemand, der zum ersten Mal einen Termin bucht.'],['Unterscheide das Nachschlagen einzelner Angaben von einem schrittweisen Lernweg.','Jemand kennt die Schnittstelle schon und sucht nur den erlaubten Feldtyp. Welche Dokumentationsform unterstützt diesen schnellen Zugriff?'],['Überlege, ob die Person Wissen nachschlagen oder einen geführten Lernweg durchlaufen soll.','Eine Anfängerin baut anhand eines durchgängigen Beispiels ihre erste kleine Anwendung. Welcher Zweck steht dabei im Vordergrund?'],['Plane für jede Zielgruppe die konkrete Aufgabe und das nötige Vorwissen.','Für Nutzende kann eine Buchungsanleitung helfen; im Betrieb wären etwa Störungsbehebung und Wiederherstellung wichtige Situationen.']]);
 unit(5,2,[['Betrachte Dokumentation als versionierbaren und gemeinsam prüfbaren Teil der Entwicklung.','Eine Änderung an der API und die zugehörige Beschreibung werden im selben Änderungsprozess überprüft. Welche Vorteile bringt diese Verbindung?'],['Gesucht ist der Hintergrund einer Entscheidung, nicht nur ihr technisches Ergebnis.','Ein Team wählt einen Nachrichtenkanal. Was müsste später über Anlass, Alternativen und Auswirkungen bekannt sein?'],['Eine Beschreibung muss zu dem Verhalten passen, das gemeinsam veröffentlicht wird.','Eine neue API-Version verändert ein Pflichtfeld. Was passiert, wenn die Dokumentation erst Wochen später dazu geprüft wird?'],['Beschreibe Situation, Alternativen, Entscheidung und bewusst akzeptierte Folgen.','Bei einer getrennten mobilen Anwendung wären etwa mehrere Auslieferungswege zu bedenken. Welche Folgen vermeidet oder erzeugt die gemeinsame Web-Auslieferung?']]);
 unit(5,3,[['Ein Kommentar sollte Informationen liefern, die der Code allein nicht gut erklärt.','„Erhöhe i“ neben i++ hilft wenig. Eine fachliche Begründung für eine ungewöhnliche Rundung kann dagegen entscheidend sein.'],['Betrachte, was eine andere Person für einen korrekten Aufruf und die Fehlerbehandlung braucht.','Bei einer Reservierung sind Pflichtfelder, Antwortdaten und der Umgang mit ungültigen Zeiträumen relevant.'],['Ein Ablauf wird nutzbar, wenn Handlungen, Verantwortung und Ergebnisse erkennbar sind.','Bei einer Störung muss klar sein, wer zuerst prüft, wann weitergegeben wird und wie der Abschluss dokumentiert wird.'],['Beschreibe Vertrag und Beispiele sowohl für Erfolg als auch für typische Fehler.','Eine neue Kontaktadresse könnte Pflichtfelder, eine erzeugte Kennung und eine verständliche Rückmeldung bei ungültigen Eingaben benötigen.']]);
 unit(5,4,[['Suche eine direkt ausführbare Handlung mit erkennbarem Ziel.','Vergleiche „Die Einstellungen sind wichtig“ mit „Öffne Einstellungen und wähle Benachrichtigungen“. Welche Form lässt sich ausführen?'],['Überlege, was vor dem Start gelten muss und woran der Erfolg erkennbar wird.','Nach dem Speichern einer Anschrift möchte eine Person wissen, ob die Änderung übernommen wurde und was bei einer Fehlermeldung hilft.'],['Eine Abbildung muss beim Finden der relevanten Stelle helfen und zum beschriebenen Stand passen.','Ein altes Bildschirmfoto zeigt einen Button, der inzwischen anders heißt. Welche Angaben oder Markierungen vermeiden Verwirrung?'],['Beschreibe Startvoraussetzung, einzelne Handlungen, sichtbaren Erfolg und einen typischen Fehler.','Beim Ändern einer Adresse könnten fehlende Berechtigungen den Ablauf verhindern. Wie führst du die Person dann verständlich weiter?']]);
 unit(5,5,[['Überlege, wie Lernende ihr Verständnis selbst sichtbar machen können.','Nach einer Vorführung lösen Teilnehmende eine ähnliche Aufgabe eigenständig. Was erfährst du dadurch, das bloßes Zuschauen nicht zeigt?'],['Wissen braucht Zuständigkeit und einen Anlass zur regelmäßigen Prüfung.','Ein Hilfetext beschreibt seit Monaten eine alte Oberfläche. Wer sollte ihn bei einer neuen Version gezielt überprüfen?'],['Multiplikatoren sollen anderen Menschen etwas erklären und auf Rückfragen eingehen können.','Eine kurze Klickfolge kann für Endnutzende reichen. Welche zusätzlichen Hintergründe braucht jemand, der später eine ganze Gruppe schult?'],['Plane eine selbst ausführbare Aufgabe, eine Beobachtung des Ergebnisses und die spätere Pflege.','Bei einer kurzen Einführung zum Export könnte jede Person eine Datei erzeugen und prüfen. Wer aktualisiert die Anleitung bei Änderungen?']]);
 unit(5,6,[['Prüfe, ob eine Person die beschriebene Aufgabe mithilfe der Anleitung tatsächlich bewältigt.','Eine fachlich richtige Anleitung kann trotzdem einen notwendigen Zwischenschritt auslassen. Wie fällt das praktisch auf?'],['Eine Anleitung beschreibt immer einen bestimmten Zustand der Anwendung.','Eine ältere Fassung verlangt ein anderes Pflichtfeld als die neue. Welche Information hilft Lesenden, die richtige Anleitung auszuwählen?'],['Automatisierung eignet sich für klar erkennbare, wiederholbare formale Probleme.','Eine Hilfeseite verweist auf eine nicht mehr vorhandene Unterseite. Lässt sich dieser Fehler regelmäßig automatisch erkennen?'],['Ermittle betroffene Texte und Abbildungen und prüfe den neuen Ablauf anschließend praktisch.','Nach einer Änderung der Passwort-Zurücksetzung könnten auch Fehlermeldungen und Support-Hinweise anzupassen sein. Was gehört zur gemeinsamen Freigabe?']]);
 unit(6,1,[['Ein Kriterium braucht einen beobachtbaren Maßstab unter benannten Bedingungen.','„Der Export funktioniert gut“ lässt sich schwer beurteilen. Welche Angaben zu Inhalt, Eingabe und erwartetem Ergebnis würden helfen?'],['Ein Nachweis muss dem tatsächlich geprüften Stand zugeordnet werden können.','Ein erfolgreicher Test der vorigen Woche sagt wenig, wenn inzwischen eine neue Fassung ausgeliefert wurde. Welche Zuordnung fehlt?'],['Achte auf Rollen für Durchführung, fachliche Bewertung und Entscheidung.','Bei einer Geräteabnahme kann die Bedienperson testen, während eine andere Rolle die verbindliche Entscheidung trifft.'],['Formuliere je Kriterium eine klare Bedingung und einen dazu passenden Nachweis.','Eine Reservierung könnte korrekt gespeichert und eine doppelte Belegung verhindert werden müssen. Wie würde jeweils ein prüfbarer Nachweis aussehen?']]);
 unit(6,2,[['Stelle vereinbartes Ergebnis und beobachtete Abweichung konkret gegenüber.','Eine Rechnung soll alle Positionen enthalten, eine bestimmte Position fehlt jedoch. Welche Angaben machen die Abweichung nachvollziehbar?'],['Achte auf die Bedeutung der Mängel und den konkreten Werkvertragsrahmen.','Ein kleiner Darstellungsfehler und eine vollständig unbrauchbare Kernfunktion sind bei der Abnahme nicht automatisch gleich zu behandeln.'],['Ein offener Punkt braucht eine überprüfbare weitere Bearbeitung.','„Wird später korrigiert“ lässt offen, wer handelt und wann das Ergebnis kontrolliert wird. Welche Vereinbarungen würden helfen?'],['Bewerte den Fehler anhand der vereinbarten Leistung und halte Entscheidung sowie Nachbesserung nachvollziehbar fest.','Eine Exportdatei mit falschen Beträgen kann fachliche Folgen haben. Welche Bedeutung hat das für Umfang, Verantwortliche und erneute Prüfung?']]);
 unit(6,3,[['Eine Übergabe soll gegen einen gemeinsam vereinbarten Umfang geprüft werden können.','Bei einer neuen Anwendung könnten Betriebsanleitung und Rückfallpaket leicht vergessen werden. Woran lässt sich Vollständigkeit systematisch abgleichen?'],['Zugangsdaten brauchen einen kontrollierten und geschützten Übergabeweg.','Ein produktives Passwort in einer allgemeinen Präsentation erreicht leicht Menschen, die diesen Zugang gar nicht benötigen.'],['Nach dem Projekt müssen Störungen und Fragen im Regelbetrieb bearbeitet werden können.','Wenn am ersten Betriebstag ein Fehler auftritt, braucht das Supportteam Zuständigkeiten, bekannte Probleme und einen verlässlichen Eskalationsweg.'],['Denke an auszuliefernde Bestandteile, Betriebswissen, Zuständigkeiten und kontrollierte Zugänge.','Bei einer Buchungsanwendung wären etwa Wiederherstellung, Überwachung und der Umgang mit Störungen wichtige Übergabesituationen.']]);
 unit(6,4,[['Vergleiche die Reichweite des ersten Einführungsschritts und die Möglichkeit, daraus zu lernen.','Eine neue Funktion wird zunächst nur in einer Filiale genutzt. Welche Erkenntnisse können vor der Ausweitung auf weitere Filialen entstehen?'],['Zwei gleichzeitig genutzte Systeme können unterschiedliche Datenstände entwickeln.','Eine Buchung wird nur im neuen System geändert. Was müsste für einen verlässlichen Vergleich mit dem alten System geklärt werden?'],['Betroffene Menschen brauchen verständliche Gründe, Vorbereitung und erreichbare Unterstützung.','Eine Oberfläche ändert sich ohne Ankündigung. Welche Schwierigkeiten könnten eine vorherige Einbindung und gezielte Unterstützung vermeiden?'],['Vergleiche Einführungsrisiko, Lernmöglichkeiten und die gemeinsame Nutzung von Daten.','Bei mehreren Filialen kann ein begrenzter erster Schritt Erfahrungen liefern. Was muss vor einer späteren Ausweitung vorbereitet sein?']]);
 unit(6,5,[['Entscheidungskriterien sollten feststehen, bevor unter Zeitdruck über den Start entschieden wird.','Eine Gruppe legt erst während einer Störung fest, was noch akzeptabel ist. Welche Unsicherheit vermeidet eine frühere Vereinbarung?'],['Die Anwendungsversion ist nur ein Teil des Zustands; inzwischen können auch Daten verändert worden sein.','Nach einem Update wurden neue Reservierungen gespeichert. Was könnte passieren, wenn nur die alte Software zurückgespielt wird?'],['Wähle eine beobachtbare Eigenschaft des tatsächlich genutzten Dienstes.','Der Server läuft, aber Buchungen scheitern. Welche Beobachtung zeigt mehr über den fachlichen Erfolg des Starts?'],['Benenne Auslöser, Entscheidung, technische Schritte und die Kontrolle des wiederhergestellten Zustands.','Bei einem fehlgeschlagenen Update müssen auch neue Daten und die Benachrichtigung Betroffener berücksichtigt werden.']]);
 unit(6,6,[['Ein Lernziel beschreibt eine Fähigkeit, deren Anwendung beobachtet werden kann.','„Kennt das Portal“ ist unklar. Wie könntest du prüfen, ob jemand eine Störung korrekt einordnet und weitergibt?'],['Unterscheide die Stimmung nach der Schulung von später beobachtbarem Handeln.','Ein Team verwendet die geübte Prüfliste zwei Wochen später zuverlässig bei echten Störungen. Welche Art von Wirkung wird hier sichtbar?'],['Ein gutes Gefühl belegt noch nicht automatisch Können oder bessere Arbeitsergebnisse.','Ein Kurs bekommt hervorragende Bewertungen. Trotzdem wurde noch nicht beobachtet, ob die Teilnehmenden eine Aufgabe selbst lösen können.'],['Leite die Übung aus einer konkreten Supportaufgabe ab und prüfe mehr als Zufriedenheit.','Teilnehmende könnten zuerst einen Übungsfall lösen und später bei einem echten Fall begleitet werden. Welche Ergebnisse würdest du vergleichen?']]);
 unit(7,1,[['Ein Vergleich benötigt einen bekannten Ausgangspunkt und vergleichbare Messbedingungen.','Ein Monat enthält Feiertage, der andere nicht. Wie könnte dieser Unterschied eine Aussage über die Wirkung einer Prozessänderung verzerren?'],['Trenne die Umsetzung eines Versuchs von der Auswertung seiner Ergebnisse.','Nach einer neuen Review-Regel werden Wartezeit und Nacharbeit gemessen. Was soll dieser Schritt über die Annahme zeigen?'],['Eine schnellere Lieferung kann zusätzliche Fehler oder Nacharbeit verursachen.','Ein Team halbiert seine Bearbeitungszeit, muss danach aber häufig korrigieren. Reicht die reine Zeitkennzahl für eine Bewertung?'],['Beschreibe Ausgangslage, eine konkrete Änderung und den späteren Vergleich.','Eine feste tägliche Review-Zeit könnte als begrenzter Versuch dienen. Welche Messung zeigt, ob Wartezeit sinkt und Qualität erhalten bleibt?']]);
 unit(7,2,[['Frage nach Bedingungen und Ursachen hinter dem sichtbaren Ereignis.','Ein Alarm blieb liegen. Welche Regeln und Rahmenbedingungen erklären das besser als die vorschnelle Aussage, jemand sei unaufmerksam gewesen?'],['Mehrere mögliche Ursachen sollen übersichtlich gruppiert werden.','Bei häufigen Exportfehlern kommen unter anderem Daten, Werkzeuge, Abläufe und Wissen infrage. Welche Darstellung hilft, diese Möglichkeiten zu ordnen?'],['Eine Maßnahme sollte zu einer begründeten Ursache passen und auf ihre Wirkung überprüft werden.','Wenn Zuständigkeiten unklar waren, behebt zusätzliche Hardware dieses Problem nicht automatisch. Welche Verbindung zwischen Ursache und Handlung wäre nachvollziehbar?'],['Sammle belegbare Ereignisse, kläre Ursachen und vereinbare überprüfbare Schritte.','Eine Zeitleiste kann zeigen, wann der Alarm einging und welche Übergaben stattfanden. Welche Fragen lassen sich danach sachlich untersuchen?']]);
 unit(7,3,[['Eine Empfehlung braucht mehr als einen behaupteten Nutzen.','Ein Werkzeug spart möglicherweise Zeit, verursacht aber Kosten und Einführungsaufwand. Welche Alternativen und Risiken sollten im Vergleich stehen?'],['Ein günstiger Eintrag in der Matrix ist zunächst eine Entscheidungshilfe, noch kein Wirkungsnachweis.','Eine kleine Regeländerung wirkt vielversprechend. Welche Annahmen würdest du vor einer breiten Einführung noch prüfen?'],['Priorisierung verliert ihre Wirkung, wenn keine echten Unterschiede sichtbar werden.','Wenn jede Aufgabe sofort zwingend ist, hilft die Liste beim Umgang mit begrenzter Zeit kaum weiter.'],['Vergleiche denselben erwarteten Nutzen mit Aufwand, Risiken und überprüfbarer Wirkung.','Eine zusätzliche Review-Regel kann wenig Geld kosten, bindet aber Arbeitszeit. Wie stellst du sie fair einem Analysewerkzeug gegenüber?']]);
 unit(7,4,[['Suche zuerst Belege dafür, wo die Zeit bei einer repräsentativen Abfrage verbraucht wird.','Ein langsamer Bildschirm kann viele Ursachen haben. Welche Messung unterscheidet eine teure Datenbankabfrage von langsamer Übertragung?'],['Unterscheide das Anzeigen einer Planung von der tatsächlichen Ausführung einer Abfrage.','Eine Anweisung verändert Daten. Was solltest du prüfen, bevor du eine Analyse startest, die diese Anweisung wirklich ausführt?'],['Zusätzlich gespeicherte Informationen können Lesen beschleunigen, erhöhen aber den Abstimmungsbedarf beim Schreiben.','Eine Summe wird neben ihren Einzelpositionen gespeichert. Was muss nach einer Änderung der Positionen ebenfalls korrekt angepasst werden?'],['Miss einen repräsentativen Fall und ändere danach gezielt eine begründete Ursache.','Eine Terminliste könnte unnötig viele Daten laden. Wie prüfst du nach einer Anpassung Geschwindigkeit und weiterhin korrekte Ergebnisse?']]);
 unit(7,5,[['Betrachte auch Zeiten, in denen eine Aufgabe auf den nächsten Schritt wartet.','Eine Änderung wird in einer Stunde programmiert und liegt danach drei Tage vor der Freigabe. Welcher Teil prägt ihre gesamte Durchlaufzeit?'],['Kennzahlen sollen Verbesserungen im eigenen Zusammenhang unterstützen.','Zwei Teams betreiben sehr unterschiedliche Systeme. Welche Probleme entstehen, wenn ihre Zahlen ohne diesen Kontext als Rangliste verwendet werden?'],['Die Maßnahme sollte den beobachteten Engpass behandeln.','Eine zusätzliche Programmiersprache verkürzt nicht automatisch eine mehrtägige Warteschlange vor einer Genehmigung. Wo würdest du den Ablauf untersuchen?'],['Betrachte Lieferhäufigkeit und Stabilität gemeinsam und suche nach einer belegbaren Ursache.','Viele kleine Auslieferungen können gut funktionieren; häufige direkte Korrekturen deuten auf zusätzliche Probleme hin. Welche Prüfschritte könnten früher helfen?']]);
 unit(7,6,[['Spätere Lesende müssen verstehen, unter welchen Bedingungen die Entscheidung sinnvoll war.','Eine damalige Beschränkung fällt inzwischen weg. Welche gespeicherten Angaben helfen zu beurteilen, ob die Entscheidung noch passt?'],['Eine Erkenntnis braucht eine verfolgte Handlung und einen späteren Blick auf deren Wirkung.','„Bessere Abstimmung nötig“ verändert noch keinen Ablauf. Was müsste aus dieser Beobachtung konkret vereinbart werden?'],['Prüfe, ob Annahmen oder Rahmenbedingungen der damaligen Entscheidung verändert wurden.','Eine Lösung wurde für wenige Nutzende gewählt und muss jetzt sehr viel mehr Last tragen. Warum ist das ein sinnvoller Anlass für einen neuen Blick?'],['Halte Versuch, beobachtetes Ergebnis, vermutete Ursachen und das weitere Vorgehen fest.','Eine tägliche Besprechung senkt die Wartezeit nicht. Welche Daten und Anpassungen wären für einen späteren neuen Versuch hilfreich?']]);
 unit(8,1,[['Es reicht, wenn eine natürliche Person mit vertretbaren Mitteln zugeordnet werden kann.','Eine interne Kennung enthält keinen Namen. In einer anderen Tabelle ist sie jedoch eindeutig einer Person zugeordnet.'],['Prüfe jedes Datenfeld anhand des konkreten Verarbeitungszwecks.','Für einen Rückruf wird ein Kontaktweg benötigt. Welche Begründung wäre nötig, um zusätzlich die Schuhgröße verpflichtend zu erfassen?'],['Einwilligung ist eine mögliche Rechtsgrundlage, aber ihre Eignung hängt von der Situation ab.','Ein freiwilliger Newsletter und die notwendige Abwicklung einer Bestellung können unterschiedliche rechtliche Grundlagen haben.'],['Beschreibe zuerst den Zweck und begründe danach, welche Angaben dafür nötig sind.','Bei einer Terminbestätigung sollte jedes zusätzliche Pflichtfeld einen nachvollziehbaren Bezug zum Zweck haben. Wer prüft die passende Rechtsgrundlage?']]);
 unit(8,2,[['Achte auf die tatsächliche Entscheidung über Zweck und wesentliche Gestaltung der Verarbeitung.','Eine Organisation entscheidet, warum Daten verarbeitet werden; ein Dienstleister setzt vereinbarte Schritte um. Welche Rolle liegt bei wem?'],['Eine Anfrage muss berechtigt zugeordnet und nachvollziehbar bearbeitet werden.','Jemand verlangt die Daten einer anderen Person per einfacher Nachricht. Welche Prüfung braucht es vor einer Herausgabe?'],['Überlege, welche Verarbeitung voraussichtlich hohe Risiken für betroffene Menschen mit sich bringt.','Eine umfassende dauerhafte Beobachtung kann andere Folgen haben als ein einfaches Kontaktformular. Welche Bewertung sollte vor dem Start erfolgen?'],['Betrachte Zweck, rechtliche Zulässigkeit, Rollen und Risiken für betroffene Beschäftigte.','Eine dauerhafte Auswertung von Bewegungen kann tief in den Arbeitsalltag eingreifen. Welche zuständigen Stellen und Schutzmöglichkeiten müssten einbezogen werden?']]);
 unit(8,3,[['Unterscheide unbefugtes Lesen, unerlaubtes Verändern und fehlende Nutzbarkeit.','Ein Termin wird ohne Berechtigung verschoben. Welche Eigenschaft der Daten ist dadurch unmittelbar beeinträchtigt?'],['Bewerte die möglichen Auswirkungen einer Verletzung der Schutzziele.','Ein Ausfall einer öffentlichen Informationsseite hat andere Folgen als der Ausfall eines lebenswichtigen Dienstes. Welche Auswirkungen sind hier maßgeblich?'],['Gesucht ist ein fortlaufender organisatorischer Umgang mit Informationssicherheit.','Risiken, Verantwortlichkeiten und Überprüfungen werden regelmäßig gemeinsam betrachtet. Das geht über die Installation eines einzelnen Sicherheitsprodukts hinaus.'],['Beschreibe je Risiko eine konkrete Auswirkung und ordne sie einem Schutzziel zu.','Unerlaubtes Lesen, falsche Daten und ein nicht erreichbarer Dienst haben verschiedene Folgen. Welche organisatorische Verantwortung verbindet die Schutzmaßnahmen?']]);
 unit(8,4,[['Rechte sollten zur konkreten Aufgabe passen und darüber hinaus begrenzt bleiben.','Ein Konto soll Berichte lesen. Braucht es gleichzeitig die Möglichkeit, sämtliche Nutzerkonten zu verändern?'],['Eine vorhandene Sicherungsdatei beweist noch keine funktionierende Wiederherstellung.','Ein Team hat tägliche Backups, kennt aber weder den Rückspielweg noch die Lesbarkeit der Dateien. Wie ließe sich das praktisch überprüfen?'],['Unterscheide technische Mechanismen von Regeln, Zuständigkeiten und vereinbarten Abläufen.','Eine Verschlüsselung arbeitet technisch. Ein festgelegtes Verfahren zur regelmäßigen Rechteprüfung braucht zusätzlich verantwortliche Personen.'],['Verbinde passende Rechte, vorbeugenden Schutz und überprüfbare Wiederherstellung.','Bei einem Administrationszugang können eine begrenzte Rolle, sichere Anmeldung und eine regelmäßige Kontrolle zusammenwirken. Welcher Nachweis passt zu jedem Schritt?']]);
 unit(8,5,[['Die Kategorie beschreibt, was mit Daten unbefugt geschieht.','Jemand verändert heimlich einen Buchungsbetrag. Unterscheide diesen Vorgang vom bloßen Mitlesen oder dem Ausfall des Dienstes.'],['An einer Grenze ändern sich Annahmen darüber, welchen Eingaben oder Beteiligten vertraut werden kann.','Eine Anfrage kommt aus einem Browser in die interne Verarbeitung. Welche Prüfungen dürfen dort nicht einfach vorausgesetzt werden?'],['Eine Maßnahme kann das Risiko senken, ohne jede Unsicherheit vollständig zu beseitigen.','Nach einer zusätzlichen Prüfung können Restgefahren bestehen. Wie wird entschieden, ob sie tragbar sind und weiter beobachtet werden müssen?'],['Beschreibe unerlaubte Handlung, fehlende Prüfung und einen Test mit getrennten Konten.','Konto A darf nur eigene Berichte sehen. Wie prüfst du, ob eine veränderte Kennung trotzdem Berichte von Konto B zugänglich macht?']]);
 unit(8,6,[['Vergleiche das tatsächliche Verhalten mit den einschlägigen verbindlichen Vorgaben.','Eine Organisation muss eine festgelegte Aufbewahrungsregel einhalten. Welche Maßnahmen und Belege zeigen, dass ihre IT dieser Vorgabe folgt?'],['Ein Nachweis muss Durchführung, Ergebnis und Bezug zur konkreten Kontrolle erkennen lassen.','Eine leere Checkliste beweist wenig. Welche Angaben sollten nach einer tatsächlich durchgeführten Rechteprüfung nachvollziehbar sein?'],['Eine Abweichung braucht eine eingeordnete Ursache und eine überprüfbare Bearbeitung.','Ein Audit stellt fehlende Prüfbelege fest. Wie werden Verantwortliche, Termin und erneute Kontrolle daraus konkret vereinbart?'],['Lege Umfang, verantwortliche Rolle, Termin und dokumentiertes Ergebnis fest.','Bei einer regelmäßigen Kontrolle von Administrationsrechten sollte auch geklärt sein, wie unberechtigte Zugänge entfernt und Änderungen nachgewiesen werden.']]);
 unit(8,7,[['Achte darauf, ob ein bestimmter Erfolg oder eine Tätigkeit geschuldet wird.','Ein Vertrag verlangt eine fertig funktionsfähige Schnittstelle. Das unterscheidet sich von einer Vereinbarung über laufende Beratungstätigkeit.'],['Prüfe, was die vertraglich vereinbarte Leistung im Kern verlangt.','Eine Beratung wird sorgfältig erbracht, garantiert aber nicht automatisch ein bestimmtes späteres wirtschaftliches Ergebnis.'],['Eine Änderung beeinflusst häufig mehr als nur eine einzelne Funktion.','Ein zusätzlicher Export benötigt Entwicklung und Tests. Welche Folgen für Zeit, Kosten, Risiken und Vereinbarungen sollten vor einer Freigabe klar sein?'],['Erfasse den Wunsch und seine Auswirkungen, bevor Umfang oder Termin stillschweigend verändert werden.','Ein weiteres Dateiformat kann Aufwand und Abnahme verändern. Wer bewertet die Folgen und wer trifft anschließend die dokumentierte Entscheidung?']]);
 unit(8,8,[['Zuerst muss klar sein, ob die betroffene Komponente in welcher Fassung tatsächlich eingesetzt wird.','Eine Sicherheitsmeldung nennt bestimmte Bibliotheksversionen. Welche Übersicht hilft beim Abgleich mit den eigenen Anwendungen?'],['Unterscheide eine allgemeine neue Regel von ihrer konkreten Anwendbarkeit auf das eigene Vorhaben.','Eine neue Vorgabe betrifft nicht automatisch jede Organisation gleich. Wer klärt Betroffenheit, Maßnahmen und Fristen?'],['Eine Änderung muss die Schwachstelle behandeln und zugleich weiterhin korrektes Verhalten ermöglichen.','Ein Bibliotheksupdate schließt eine Lücke, verändert aber eine verwendete Schnittstelle. Welche Prüfungen braucht die Freigabe?'],['Kläre Betroffenheit und Risiko und plane danach Behandlung, Prüfung und dokumentierte Freigabe.','Ein Update könnte kurzfristig eingespielt werden müssen. Welche Abhängigkeiten und Rückfallmöglichkeiten dürfen dabei nicht übersehen werden?']]);
 unit(9,1,[['Ein Ziel braucht ein beobachtbares Ergebnis und einen definierten Bezug zur Planung.','„Schulung verbessern“ ist unklar. Welche Angaben zu Zielgruppe, Können und Zeitpunkt machen daraus ein überprüfbares Teilprojektziel?'],['Unterscheide die Durchführung einer Arbeit von der Ergebnisverantwortung.','Mehrere Personen bearbeiten ein Paket. Wer sorgt dafür, dass über sein Ergebnis verbindlich entschieden wird?'],['Betrachte die Zerlegung des Projektumfangs, nicht zuerst die zeitliche Reihenfolge.','Ein Portalprojekt wird in Oberfläche, Datenübernahme und Schulung unterteilt. Welche Übersicht über Arbeitspakete entsteht daraus?'],['Formuliere ein überprüfbares Schulungsergebnis und trenne Durchführung, Verantwortung und Beteiligung.','Bei einer Anleitung können eine Person schreiben, eine andere das Ergebnis verantworten und Fachleute Rückmeldung geben.']]);
 unit(9,2,[['Überlege, wie bald ein nutzbares Zwischenergebnis überprüft und angepasst werden kann.','Bei unklaren Bedienwünschen zeigt ein Team früh einen kleinen funktionsfähigen Ausschnitt. Was lässt sich daraus für den nächsten Schritt lernen?'],['Gesucht ist das gemeinsam verstandene Qualitätsniveau eines fertigen Inkrements.','Zwei Personen meinen mit „fertig“ Unterschiedliches: programmiert oder zusätzlich geprüft und integriert. Welche Vereinbarung verhindert diese Unklarheit?'],['Unterscheide eine optionale Teamvereinbarung von einem verbindlichen Bestandteil des Scrum-Rahmens.','Ein Team legt fest, wann es eine Aufgabe gut genug versteht, um zu beginnen. Muss daraus automatisch eine allgemeine Scrum-Pflicht entstehen?'],['Kläre gemeinsam die Bedeutung von Fertigstellung und die noch fehlenden Nachweise.','Eine Funktion ist bedienbar, doch wichtige Fehlerszenarien sind ungeprüft. Welche gemeinsamen Kriterien bestimmen den weiteren Umgang damit?']]);
 unit(9,3,[['Berücksichtige sowohl Betroffenheit als auch Einfluss auf das Vorhaben.','Auch ein externes Supportteam kann vom neuen Portal betroffen sein, obwohl es nicht zum Entwicklungsteam gehört.'],['Eine Analyse soll zu passender Einbindung und Kommunikation führen.','Betrieb und Endnutzende haben unterschiedliche Fragen. Welche Art von Beteiligung wäre für jede Gruppe sinnvoll?'],['Eine geplante Nachricht braucht klare Zuständigkeiten und einen konkreten Rahmen.','„Wir informieren regelmäßig“ lässt offen, wer wen worüber und auf welchem Weg erreicht. Welche Angaben würdest du ergänzen?'],['Unterscheide Informationsbedarf, Kanal, Zeitpunkt und verantwortliche Person je Zielgruppe.','Die Leitung braucht eine Entscheidungsvorlage, während Nutzende konkrete Handlungshinweise benötigen. Wie passt du Umfang und Zeitpunkt an?']]);
 unit(9,4,[['Unterscheide ein bereits eingetretenes Problem von einem möglichen zukünftigen Ereignis.','Eine Lieferung könnte sich verspäten. Am nächsten Tag steht fest, dass der Termin bereits verfehlt wurde. Wie verändert sich ihre Einordnung?'],['Beschreibe Ereignis, mögliche Wirkung, Bewertung und verantwortliche Behandlung nachvollziehbar.','Ein Zulieferer könnte verspätet liefern. Welche Angaben fehlen noch, um daraus eine bearbeitbare statt nur vage Sorge zu machen?'],['Die nächste verantwortliche Ebene muss erkennen, welche Entscheidung tatsächlich benötigt wird.','Ein Team meldet „Termin kritisch“. Welche Optionen, Folgen und Frist machen daraus eine nutzbare Entscheidungsvorlage?'],['Trenne mögliche Ursache, erwartete Wirkung und eine konkrete Entscheidungsvorlage.','Eine spätere Datenlieferung kann Tests verzögern. Welche Handlungsoptionen und Auswirkungen auf den Termin sollten Verantwortliche abwägen können?']]);
 unit(9,5,[['Der Nachfolger darf erst beginnen, wenn alle erforderlichen Vorgänger abgeschlossen sind.','Eine Tätigkeit wartet auf Ergebnisse, die an Tag 3 und Tag 6 fertig sind. Welcher Abschluss begrenzt ihren frühesten Start?'],['Vergleiche die vollständigen voneinander abhängigen Wege bis zum Projektende.','Ein kurzer Nebenweg endet früh, ein anderer Weg benötigt deutlich länger. Welcher davon begrenzt den frühestmöglichen Abschluss?'],['Betrachte eine mögliche Verschiebung im Verhältnis zum geplanten Projektende.','Ein Arbeitspaket kann etwas später beginnen, ohne den Gesamtabschluss zu verändern. Welche zeitliche Reserve beschreibt das?'],['Zeichne die beiden parallelen Wege und vergleiche ihre Dauer einschließlich gemeinsamem Anfang und Ende.','Bei A = 1, B = 4, C = 2 und D = 3 liegen die Wege A–B–D und A–C–D vor. Rechne danach mit den Werten der Aufgabe.']]);
 unit(9,6,[['Arbeitsmenge und verstrichene Kalenderzeit sind unterschiedliche Größen.','Zwei Personentage Arbeit können länger als zwei Tage dauern, wenn nur eine halbe Person pro Tag verfügbar ist oder Abhängigkeiten warten lassen.'],['Bei PERT wird die wahrscheinlichste Schätzung stärker gewichtet als die beiden Randwerte.','Für andere Werte 2, 4 und 8 würdest du (2 + 4 × 4 + 8) / 6 rechnen. Setze anschließend die Zahlen der Frage ein.'],['Eine Zahl wird erst mit Annahmen und Randbedingungen nachvollziehbar.','Zehn Stunden können mit oder ohne Einarbeitung gemeint sein. Welche Angaben braucht eine andere Person, um die Schätzung sinnvoll zu verwenden?'],['Berechne zuerst den gewichteten Schätzwert und trenne ihn von der eigentlichen Terminplanung.','Auch ein bekannter Aufwand sagt noch nichts über Teamverfügbarkeit, Wartezeiten und Abhängigkeiten aus. Welche dieser Bedingungen sind noch offen?']]);
 unit(9,7,[['Unterscheide geplante Leistung, tatsächlich erbrachte Leistung und tatsächlich angefallene Kosten.','Eine Aufgabe ist nur teilweise erledigt, hat aber bereits viel Geld verbraucht. Welcher Wert beschreibt die erreichte Leistung anhand ihres Budgets?'],['Vergleiche den Wert der erreichten Leistung mit den tatsächlich dafür entstandenen Kosten.','Bei EV = 6.000 und AC = 10.000 würde der Quotient 6.000 / 10.000 betrachtet. Setze anschließend die Werte der Frage ein.'],['SPI ist ein Verhältnis von Leistungswerten und keine direkte Zahl von Verspätungstagen.','Wenn weniger Leistungswert erreicht als geplant wurde, zeigt die Kennzahl eine Abweichung. Welche zusätzlichen Informationen brauchst du für eine Terminprognose?'],['Trenne Kosten- und Planvergleich und erkläre die Zahlen anschließend im fachlichen Kontext.','Bei anderen Werten EV = 6.000, AC = 8.000 und PV = 10.000 ergeben sich zwei unterschiedliche Quotienten. Welche Ursachen würdest du danach untersuchen?']]);
 unit(9,8,[['Eine Einführung betrifft neben Technik auch beteiligte Gruppen und abgestimmte Zeitpunkte.','Ein Portal ist bereit, aber Support und Anwender kennen den Starttermin nicht. Welche Abstimmung fehlt vor der Einführung?'],['Menschen sollen sichere Handlungen im konkreten Arbeitsalltag üben können.','Bei einer verdächtigen Nachricht hilft eine praktische Übung zum Erkennen und Melden mehr als eine bloße Liste von Schlagwörtern.'],['Suche einen Nachweis, dass Wissen in einer passenden Situation tatsächlich angewendet wird.','Nach einer Schulung führt jemand einen echten Standardfall selbstständig korrekt aus. Was belegt das im Vergleich zu einer bloßen Anwesenheitsliste?'],['Verbinde Bereitschaft der Technik mit Kommunikation, Unterstützung und prüfbarer Anwendung des Wissens.','Vor dem Start einer neuen Anwendung sollten Zuständigkeiten, Hilfewege und die spätere Kontrolle des Einführungserfolgs feststehen.']]);
 const glossary=[
 {term:'API',aliases:['APIs'],definition:'Eine definierte Schnittstelle, über die Software Funktionen oder Daten einer anderen Software nutzen kann. Ihr Vertrag beschreibt etwa erlaubte Anfragen, Antworten und Fehler.',example:'Eine Termin-App fragt freie Termine über eine API ab. Die Oberfläche muss dafür nicht direkt auf die Datenbank zugreifen.'},
 {term:'SQL',definition:'Eine Sprache für relationale Datenbanken. Mit ihr lassen sich Daten abfragen und ändern sowie Tabellen und Regeln definieren.',example:'SELECT name FROM kunde fragt die Namen aus einer Kundentabelle ab. Änderungen brauchen passende Berechtigungen und sorgfältig gewählte Bedingungen.'},
 {term:'REST',aliases:['REST-API'],definition:'Ein Architekturstil für verteilte Systeme. In HTTP-APIs werden Ressourcen häufig über URLs und passende Methoden angesprochen; REST umfasst außerdem weitere Regeln, etwa zustandslose Anfragen.',example:'GET /termine/17 kann einen vorhandenen Termin abfragen. Ein zusätzlicher Endpunkt allein macht eine gesamte Schnittstelle noch nicht automatisch REST-konform.'},
 {term:'Normalisierung',aliases:['normalisieren','normalisiert'],definition:'Die systematische Prüfung und Aufteilung relationaler Tabellen anhand von Schlüsseln und funktionalen Abhängigkeiten. Sie hilft, unnötige Wiederholungen und Änderungsprobleme zu vermeiden.',example:'Ein Artikelname wird beim Artikel gespeichert. Bestellpositionen verweisen über die Artikel-ID darauf, statt den Namen in jeder Bestellung erneut zu pflegen.'},
 {term:'Redundanz',aliases:['Redundanzen'],definition:'Dieselbe Information ist mehrfach gespeichert. Bei Änderungen können dadurch widersprüchliche Datenstände entstehen; bewusst eingesetzte Redundanz muss kontrolliert gepflegt werden.',example:'Eine Adresse steht in fünf Tabellen. Wird nur eine Kopie geändert, zeigen die anderen vier weiterhin den alten Stand.'},
 {term:'Kardinalität',aliases:['Kardinalitäten'],definition:'Beschreibt die erlaubte Anzahl von Beziehungspartnern. Minima wie 0 oder 1 zeigen, ob eine Zuordnung optional oder verpflichtend ist; Maxima wie 1 oder n zeigen ihre Obergrenze.',example:'Eine Kundin kann 0 bis n Bestellungen haben; jede Bestellung gehört in diesem Modell genau einer Kundin.'},
 {term:'1NF',aliases:['erste Normalform','ersten Normalform'],definition:'Die erste Normalform verlangt atomare Attributwerte und vermeidet wiederholende Gruppen. Was als einzelner Wert gilt, wird für den jeweiligen fachlichen Datentyp festgelegt.',example:'Wenn Telefonnummern einzeln gesucht und verwaltet werden sollen, werden mehrere Nummern nicht als kommaseparierte Liste in einem Feld abgelegt.'},
 {term:'2NF',aliases:['zweite Normalform','zweiten Normalform'],definition:'Die Tabelle erfüllt die 1NF. Außerdem hängt jedes Nichtschlüsselattribut vollständig von jedem Kandidatenschlüssel ab: kein solches Attribut wird bereits durch einen echten Teil eines Kandidatenschlüssels bestimmt.',example:'In Teilnahme(person_id, kurs_id, personenname) bestimmt schon person_id den Namen. Die Personenangaben gehören deshalb in eine eigene Personentabelle.'},
 {term:'3NF',aliases:['dritte Normalform','dritten Normalform'],definition:'Für eine Tabelle in 1NF gilt bei jeder nichttrivialen funktionalen Abhängigkeit X → A: X ist ein Superschlüssel oder A gehört zu einem Kandidatenschlüssel. Im einfachen Kursfall vermeidet das transitive Abhängigkeiten von Nichtschlüsselattributen.',example:'Wenn mitarbeiter_id die abteilungs_id bestimmt und diese den Abteilungsnamen, wird der Name in der Abteilungstabelle gepflegt.'},
 {term:'Entität',aliases:['Entitäten'],definition:'Ein fachlich unterscheidbares Objekt, über das Daten gespeichert werden. Gleichartige Objekte werden zu einem Entitätstyp zusammengefasst.',example:'Kundin 17 ist eine einzelne Entität. Der Entitätstyp Kunde beschreibt gemeinsam die Eigenschaften solcher Kundenobjekte.'},
 {term:'Attribut',aliases:['Attribute','Attributen'],definition:'Eine benannte Eigenschaft eines beschriebenen Objekts oder Entitätstyps.',example:'Bei einem Kunden können kundennummer und name Attribute sein. Der konkrete Name ist ein Wert dieses Attributs.'},
 {term:'Primärschlüssel',aliases:['Primärschlüssels'],definition:'Ein ausgewählter Kandidatenschlüssel, der jeden Datensatz eindeutig bezeichnet. Seine Werte dürfen nicht NULL sein. Er kann aus einer oder mehreren Spalten bestehen.',example:'kunde_id identifiziert einen Kundendatensatz zuverlässig, auch wenn mehrere Menschen denselben Namen haben.'},
 {term:'Fremdschlüssel',aliases:['Fremdschlüssels','Fremdschlüsseln'],definition:'Ein Verweis auf einen geeigneten eindeutigen Schlüssel einer referenzierten Tabelle. Eine Fremdschlüsselregel sichert den Bezug ab; ob ein leerer Verweis erlaubt ist, hängt unter anderem von NULL-Regeln ab.',example:'bestellung.kunde_id verweist auf kunde.kunde_id. So lässt sich eine Bestellung dem passenden Kunden zuordnen.'},
 {term:'Kandidatenschlüssel',aliases:['Kandidatenschlüssels'],definition:'Eine minimale Menge von Attributen, deren Werte jeden Datensatz eindeutig bestimmen. Minimal bedeutet, dass kein enthaltenes Attribut dafür weggelassen werden kann.',example:'Wenn eine Kombination aus Kursnummer und Personennummer eine Teilnahme eindeutig bestimmt und beide Teile benötigt werden, ist sie ein Kandidatenschlüssel.'},
 {term:'Funktionale Abhängigkeit',aliases:['funktionalen Abhängigkeit','funktionale Abhängigkeiten','funktionalen Abhängigkeiten'],definition:'X → Y bedeutet: Gleiche Werte von X müssen gleiche Werte von Y haben. Das folgt aus den fachlichen Regeln und lässt sich nicht allein aus zufällig vorhandenen Beispieldaten beweisen.',example:'Wenn jede Artikel-ID genau einen Artikel beschreibt, bestimmt artikel_id den Artikelnamen.'},
 {term:'m:n-Beziehung',aliases:['m:n','n:m'],definition:'Auf beiden Seiten einer Beziehung können mehrere Partner zugeordnet sein. Im relationalen Modell wird jede einzelne Zuordnung üblicherweise in einer Verbindungstabelle gespeichert.',example:'Eine Person kann mehrere Kurse besuchen, ein Kurs mehrere Personen haben. Teilnahme verbindet jeweils eine Person mit einem Kurs.'},
 {term:'1:n-Beziehung',aliases:['1:n'],definition:'Ein Datensatz auf einer Seite kann mehreren Datensätzen auf der anderen Seite zugeordnet sein. Jeder dieser Datensätze gehört im beschriebenen Modell höchstens einem Partner der ersten Seite.',example:'Eine Abteilung besitzt mehrere Arbeitsplätze. Jeder Arbeitsplatz gehört in diesem Modell genau einer Abteilung.'},
 {term:'1:1-Beziehung',aliases:['1:1'],definition:'Auf jeder Seite ist einem Datensatz höchstens ein Partner zugeordnet. Ob die Zuordnung verpflichtend ist, wird zusätzlich mit der minimalen Kardinalität beschrieben.',example:'Jede ausgegebene Zugangskarte gehört genau einer Person, und jede Person bekommt in diesem Modell genau eine Zugangskarte.'},
 {term:'Stakeholder',aliases:['Stakeholdern'],definition:'Eine Person oder Gruppe, die ein Vorhaben beeinflusst oder von dessen Verlauf beziehungsweise Ergebnis betroffen ist.',example:'Bei einem neuen Portal zählen neben Nutzenden auch Betrieb, Support und fachliche Verantwortliche zu den beteiligten Gruppen.'},
 {term:'Transaktion',aliases:['Transaktionen'],definition:'Fasst zusammengehörige Datenbankoperationen zu einer Einheit zusammen. Ihre Eigenschaften helfen, fachliche Regeln auch bei Fehlern und gleichzeitigen Zugriffen einzuhalten.',example:'Bei einer Umbuchung müssen das Freigeben des alten und das Belegen des neuen Platzes gemeinsam korrekt abgeschlossen werden.'}
 ];
